GCS_B3_COMM(Input1_:= FALSE, Input2_:=FALSE, Input3_:=FALSE, WATCHDOG_:= GCS_B3_GW_WD_1, WATCHDOG_EN_:=TRUE, PICKUP_TIME_:=T#5S, DROPOUT_TIME_:=T#20S, DATA_READY_:=GW_BootUpComplete, IED_LOSS_=>GCS_B3_COM);
GCS_B_COMM(Input1_:= FALSE, Input2_:=FALSE, Input3_:=FALSE, WATCHDOG_:= GCS_B_GW_WD, WATCHDOG_EN_:=TRUE, PICKUP_TIME_:=T#5S, DROPOUT_TIME_:=T#20S, DATA_READY_:=GW_BootUpComplete, IED_LOSS_=>GCS_B_COM);
