GW_B_to_LSP_B3_WD:=Calender.Sec; GW_B_to_LSP_B_WD:=Calender.Sec; GW_B_TO_IOSRV01_WD:=Calender.Sec; GW_TO_GCS_B3_WD:=Calender.Sec; GW_TO_GCS_B_WD:=Calender.Sec; GWA_COUNTER.instMag:=DWORD_TO_REAL(CALENDER.Sec);
